def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def _info(t):
    """Adds parent[k] (-1 for the root) and depth[k]. Parents come before children in level order."""
    vals, left, right = _links(t)
    n = len(vals)
    par = [-1] * n
    depth = [0] * n
    for k in range(n):
        for c in (left[k], right[k]):
            if c != -1:
                par[c] = k
                depth[c] = depth[k] + 1
    return vals, left, right, par, depth


def answerQueries(tree, ops):
    vals, left, right, par, depth = _info(tree)
    n = len(vals)
    where = {v: k for k, v in enumerate(vals)}
    LOG = max(1, max(depth).bit_length())
    up = [par]
    for j in range(1, LOG):
        prev = up[-1]
        up.append([prev[x] if prev[x] == -1 else prev[prev[x]] for x in range(n)])

    def lift(x, k):
        j = 0
        while k and x != -1:
            if k & 1:
                x = up[j][x]
            k >>= 1
            j += 1
        return x

    def lca(a, b):
        if depth[a] < depth[b]:
            a, b = b, a
        a = lift(a, depth[a] - depth[b])
        if a == b:
            return a
        for j in range(LOG - 1, -1, -1):
            if up[j][a] != up[j][b]:
                a = up[j][a]
                b = up[j][b]
        return par[a]

    out = []
    for t, a, b in ops:
        if t == 1:
            x = where[a]
            if b > depth[x]:
                out.append(-1)
            else:
                out.append(vals[lift(x, b)])
        else:
            x, y = where[a], where[b]
            l = lca(x, y)
            out.append(vals[l] if t == 2 else depth[x] + depth[y] - 2 * depth[l])
    return out
